package com.kioskmdm;
import android.app.*;import android.content.*;import android.content.pm.*;import android.os.*;import android.text.InputType;import android.widget.*;import java.util.*;
public class AdminActivity extends Activity {LinearLayout l;protected void onCreate(Bundle b){super.onCreate(b);login();}
 void login(){l=UI.root(this,"מנהל");EditText p=new EditText(this);p.setHint("קוד מנהל");p.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_VARIATION_PASSWORD);l.addView(p);Button x=UI.b(this,"כניסה");x.setOnClickListener(v->{if(Prefs.pin(this,p.getText().toString()))menu();else UI.msg(this,"קוד שגוי");});l.addView(x);setContentView(l);}
 void menu(){l=UI.root(this,"מנהל");Button m=UI.b(this,"ניהול");m.setOnClickListener(v->manage());l.addView(m);Button t=UI.b(this,"מצב תחזוקה");t.setOnClickListener(v->{Policy.maintenance(this,true);try{stopLockTask();}catch(Exception ignored){}UI.msg(this,"מצב תחזוקה פעיל");});l.addView(t);Button lock=UI.b(this,"סיום מצב תחזוקה ונעילה");lock.setOnClickListener(v->{Policy.maintenance(this,false);startActivity(new Intent(this,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_CLEAR_TOP));finish();});l.addView(lock);setContentView(l);}
 void manage(){l=UI.root(this,"ניהול");TextView h=new TextView(this);h.setText("לחיצה על אפליקציה בוחרת אותה כראשית. המתג משבית/מחזיר אפליקציה. חבילות מערכת קריטיות מוגנות.");l.addView(h);PackageManager pm=getPackageManager();Intent q=new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_LAUNCHER);List<ResolveInfo> list=pm.queryIntentActivities(q,PackageManager.MATCH_DISABLED_COMPONENTS);Set<String> seen=new HashSet<>();for(ResolveInfo r:list){String pkg=r.activityInfo.packageName;if(!seen.add(pkg)||pkg.equals(getPackageName()))continue;LinearLayout row=new LinearLayout(this);row.setOrientation(LinearLayout.HORIZONTAL);Button b=UI.b(this,r.loadLabel(pm)+"\n"+pkg);b.setOnClickListener(v->{Prefs.main(this,pkg);Policy.setBlocked(this,pkg,false);Policy.apply(this,pkg);UI.msg(this,"האפליקציה הראשית שונתה");});row.addView(b,new LinearLayout.LayoutParams(0,-2,1));Switch sw=new Switch(this);sw.setText("חסום");sw.setChecked(Prefs.blocked(this).contains(pkg));sw.setEnabled(!Policy.isProtected(this,pkg));sw.setOnCheckedChangeListener((v,on)->Policy.setBlocked(this,pkg,on));row.addView(sw);l.addView(row);}setContentView(l);}
}